/**
 * Customer tier and promotional coupon discount logic (Topological Level 0).
 */

export function tier_discount_rate(tier: string): number {
  let normalized = tier.trim().toLowerCase();
  if ((normalized === "platinum")) {
    return 0.15;
  }
  if ((normalized === "gold")) {
    return 0.1;
  }
  if ((normalized === "silver")) {
    return 0.05;
  }
  return 0.0;
}

export function apply_tier_discount(subtotal: number, tier: string): number {
  if ((subtotal <= 0.0)) {
    return 0.0;
  }
  let rate = tier_discount_rate(tier);
  return (Math.round(((subtotal * rate) + Number.EPSILON) * Math.pow(10, 2)) / Math.pow(10, 2));
}

export function coupon_discount_amount(subtotal: number, coupon_code: string): number {
  if ((subtotal <= 0.0)) {
    return 0.0;
  }
  let code = coupon_code.trim().toUpperCase();
  if ((code === "SAVE10")) {
    return (Math.round(((subtotal * 0.1) + Number.EPSILON) * Math.pow(10, 2)) / Math.pow(10, 2));
  }
  if ((code === "WELCOME20")) {
    return Math.min((Math.round(((subtotal * 0.2) + Number.EPSILON) * Math.pow(10, 2)) / Math.pow(10, 2)), 50.0);
  }
  if ((code === "FLAT15")) {
    return ((subtotal >= 75.0) ? 15.0 : 0.0);
  }
  return 0.0;
}

export function best_discount(subtotal: number, tier: string, coupon_code: string): number {
  if ((subtotal <= 0.0)) {
    return 0.0;
  }
  let tier_amt = apply_tier_discount(subtotal, tier);
  let coupon_amt = coupon_discount_amount(subtotal, coupon_code);
  let combined = (((tier_amt > 0.0) && (coupon_amt > 0.0)) ? (tier_amt + (coupon_amt * 0.5)) : Math.max(tier_amt, coupon_amt));
  let cap = (Math.round(((subtotal * 0.3) + Number.EPSILON) * Math.pow(10, 2)) / Math.pow(10, 2));
  return (Math.round((Math.min(combined, cap) + Number.EPSILON) * Math.pow(10, 2)) / Math.pow(10, 2));
}
